function openAddressModal(e){e.preventDefault();document.querySelector(".change-address-modal").classList.add("active");getAddressList().then((function(e){renderAddressModal(e)})).catch((function(e){console.error("Có lỗi khi lấy danh sách địa chỉ:",e);$("#address-container2").html("<p>Không thể tải danh sách địa chỉ.</p>")}))}function renderAddressModal(e){const n=$("#address-container2");n.empty();e.forEach((function(e){const r=`\n             <div class="address-item" onclick="selectAddressItem(event);">\n                <div class="flex-roww" style="justify-content: space-between; align-items: start">\n                    <div class="address-info">\n                        <p><span class="receiver">${e.receiver}</span> |   <span class="phone">${e.phone}</span></p>\n                        <p class="id" hidden><%=a.id%></p>\n                        <p style="margin-top: 5px">Địa chỉ: <span class="address">${e.province} - ${e.district} - ${e.village} - ${e.detail}</span></p>\n                    </div>\n                </div>\n                <div class="seperate-horizontal-90"></div>\n            </div>\n        `;n.append(r)}))}document.addEventListener("DOMContentLoaded",(function(){const e=document.querySelector("#paymentForm");e.addEventListener("submit",(async function(e){e.preventDefault();const n=this.querySelector('input[name="address-input"]');if(!document.querySelector(".chosen-address .receiver"))showInfoToast2("Hãy chọn địa chỉ giao hàng!","none");var r=document.querySelector(".chosen-address .receiver").innerText;var t=document.querySelector(".chosen-address .phone").innerText;var o=document.querySelector(".chosen-address .address").innerText;var c=r+" ("+t+")   |"+o;n.value=c;try{const e=true;if(e){console.log("Submitting form...");this.submit()}else{console.log("Form cannot be submitted.")}}catch(e){console.error("Error occurred during voucher check:",e)}}))}));function checkVoucher(e){console.log("check voucher");return new Promise(((n,r)=>{var t=document.querySelector('input[name="voucher"]').value;if(t===""){document.querySelector(".message-error").innerText="";n(true);return}var o=[];const c=document.querySelectorAll('input[name="cart-id"]');c.forEach((function(e){o.push(e.value)}));$.ajax({type:"POST",url:"payment",data:{a:"voucher",voucher:t,cartIds:JSON.stringify(o),morea:e},success:function(r){console.log("data:"+r);if(e!=null){if(r==="true"){n(true)}else{$("#payment-response").html(r);n(false)}}else{$("#payment-response").html(r);n(false)}},error:function(e){$("#payment-response").html(e.responseText);r(e)}})}))}function applyVoucher(e,n){document.querySelector("#total-money").innerText=e;document.querySelector("#discount-money").innerText=n;document.querySelector(".message-error").innerText=""}function cancelVoucher(e){document.querySelector("#total-money").innerText=document.querySelector('input[name="total-money-input"]').value.toLocaleString("vi-VN")+" ₫";document.querySelector("#discount-money").innerText="0";document.querySelector(".message-error").innerText=e}function selectAddressItem(e){let n=e.currentTarget.querySelector(".receiver").innerText;let r=e.currentTarget.querySelector(".phone").innerText;let t=e.currentTarget.querySelector(".address").innerText;document.querySelector(".chosen-address .receiver").innerText=n;document.querySelector(".chosen-address .phone").innerText=r;document.querySelector(".chosen-address .address").innerText=t;document.querySelector(".change-address-modal").classList.remove("active")}